const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const countryName = 'Canada';
  const aoi = ee.FeatureCollection('USDOS/LSIB_SIMPLE/2017')
    .filter(ee.Filter.eq('country_na', countryName))
    .first()
    .geometry();

  const startDate = '2023-10-24';
  const endDate = '2023-10-25';

  // 2. Data Acquisition & Check
  // Use MODIS Thermal Anomalies/Fire collection. It contains points of detected fires.
  const modisFires = ee.ImageCollection('MODIS/061/MCD14DL')
    .filterDate(startDate, endDate)
    .filterBounds(aoi);

  // Get the count of all detected thermal anomalies.
  const totalDetections = modisFires.size().getInfo();

  if (totalDetections === 0) {
    console.log(`Date: ${startDate}`);
    console.log(`Total thermal anomalies detected in ${countryName}: 0`);
    console.log("No fires were detected on this day.");
    console.log("A: Yes");
    return;
  }

  // 3. Processing: Filter for high-confidence fires.
  // Confidence is a value from 0-100. We'll consider >= 85 as a high-confidence fire.
  const highConfidenceFires = modisFires.filter(ee.Filter.gte('MaxFRP', 40));

  // 4. Calculation
  const highConfidenceCount = highConfidenceFires.size().getInfo();

  // 5. Validation & Final Answer
  console.log(`Query Date: ${startDate}`);
  console.log(`Location: ${countryName}`);
  console.log(`Total MODIS thermal detections: ${totalDetections}`);
  console.log(`High-confidence fires (MaxFRP > 40): ${highConfidenceCount}`);

  if (highConfidenceCount > 0) {
    console.log("Evidence of active fires was found.");
    console.log("A: Yes");
  } else {
    console.log("No high-confidence active fires were detected, though some thermal anomalies may exist.");
    console.log("B: No");
  }
}

async function initEE() {
  try {
    await new Promise((resolve, reject) => {
      ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
      ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
  } catch (e) {
    console.error(`An error occurred: ${e.message}`);
    console.log("D: If image, collection, or band names are incorrect, syntax or method error, wrong method, or memory issue, etc.");
  }
}

initEE();
